#!/usr/bin/env bash
set -euo pipefail

echo 'SHORT16 개별 1픽 + MISS Guard V1 프로젝트 생성 시작'
TMP_TGZ="$(mktemp /tmp/binaryguard.XXXXXX.tgz)"
cat > "$TMP_TGZ.b64" <<'B64EOF'

B64EOF
base64 -d "$TMP_TGZ.b64" > "$TMP_TGZ"
tar -xzf "$TMP_TGZ" -C .
rm -f "$TMP_TGZ" "$TMP_TGZ.b64"
echo '파일 생성 완료 · 좌우/사다리수/홀짝 독립 SHORT16 + MISS Guard'
if git rev-parse --is-inside-work-tree >/dev/null 2>&1; then
  git add .
  git commit -m 'Add Bubble SHORT16 Binary Guard V1' || true
  git push || true
fi
echo '완료: GitHub Actions > Build Android APK > Artifact BubbleShort16BinaryGuardV1-debug-apk'
echo '패키지: com.bubbleladder.short16binaryguardv1'
